    "help.insertion_loss.source": "Insertion Loss / Messschaltung",
    "help.insertion_loss.use": "Dämpfung nur bei gleicher Frequenz, Quell-/Lastimpedanz und Messart vergleichen.",
    "help.loss_frequency.title": "Bezugsfrequenz der Dämpfung",
