    "profiles.empty": "Noch keine Suchprofile gespeichert.",
    "profiles.description": "Speichert Kategorie, Suche, Filter, Spalten und Messbedingungen in diesem Browser. Die Spaltenvorgabe je Kategorie wird beim Öffnen nicht überschrieben. Browserdaten sind nicht im Datenbankarchiv enthalten.",
