    "profiles.loaded": "Suche geöffnet. Die Treffer beruhen auf dem aktuellen Datenbestand.",
    "profiles.storage": "Suchprofile konnten nicht gelesen oder gespeichert werden. Browser-Speicher prüfen; vorhandene Daten bleiben erhalten.",
    "profiles.corrupt": "Gespeicherte Suchprofile haben ein unbekanntes oder beschädigtes Format. Vorhandene Daten werden nicht überschrieben.",
