    "home.more": "Mehr erfahren",
    "home.tile.selection": "Bauteilauswahl",
    "home.tile.selection.short": "Nach elektrischen Eigenschaften filtern",
    "home.tile.selection.detail": "Kategorie wählen, passende Parameter eingrenzen und Kandidaten in der Tabelle vergleichen.",
    "home.tile.selection.action": "Bauteile auswählen",
    "home.tile.simulation": "Simulation",
    "home.tile.simulation.short": "SPICE-Modelle finden und zuordnen",
    "home.tile.simulation.detail": "Modelle suchen oder importieren, Symbolpins zuordnen und vorhandene Prüfergebnisse ansehen. Die Simulation erfolgt in KiCad.",
    "home.tile.simulation.action": "Simulation vorbereiten",
    "home.tile.libraries": "Bibliotheken",
    "home.tile.libraries.short": "Symbole und Footprints durchsuchen",
    "home.tile.libraries.detail": "Installierte Bibliotheken durchsuchen, Footprints und 3D-Verfügbarkeit ansehen und Referenzen für KiCad übernehmen.",
    "home.tile.libraries.action": "Footprints ansehen",
    "home.stat.symbols": "Symbole",
    "home.stat.facts": "Herstellerwerte lokal",
    "home.stat.modelNote": "Diese Modelle können Bauteilen zugeordnet werden.",
    "home.footer.local": "Lokaler Bestand · KiCad Parts Manager",
    "home.program.title": "Hilfe & KiCad-Anbindung",
    "home.program.intro": "KiCad Parts Manager hilft dir, Bauteile für Schaltplan, Leiterplatte und Simulation anhand ihrer elektrischen Eigenschaften auszuwählen. Schaltungsentwurf und Simulation erfolgen in KiCad.",
    "home.program.features": "Was du damit machen kannst",
    "home.program.catalog": "Installierte Bibliotheken mit kompakten Kategorieprofilen durchsuchen und passende Filter verwenden. Weitere Parameter, Temperatur und Qualifikationen sind wählbar. Unklare Kategorien bleiben neutral; generische SIM-Modelle erhalten keine behaupteten Herstellergrenzen. Widerstände nach Funktion und Kondensatoren nach Technologie auswählen; Bauform über den Gehäuse-/Footprintfilter eingrenzen. Die Suche durchsucht den Bestand im aktuellen Arbeitsbereich. Ein Kategoriewechsel leert die Suche; Tabellenfilter grenzen die gewählte Gruppe ein. Kurze Eingaben wie 100nF 0805 oder 10mR 2W mit Enter übernehmen: Kategorie und technische Filter werden automatisch gesetzt. Widerstand, Kapazität, Induktivität und Leistung erscheinen mit passenden Einheiten. Die entsprechenden Tabellenfilter akzeptieren Einheiten und gebräuchliche Schreibweisen; ohne Einheit gilt die am Eingabefeld angegebene Einheit. Schalter und Relais nach Funktion auswählen; Sicherungen unter Schutzbauteilen. Jumper stehen bei Steckverbindern, Drehgeber bei Sensoren. Kontaktanordnung und elektrische Kennwerte werden über die Tabellenfilter eingegrenzt. Eigene Kategoriezuordnungen für einzelne oder mehrere Bauteile speichern, rückgängig machen oder auf die automatische Zuordnung zurücksetzen. Sie bleiben bei erneuten Imports erhalten; die Originalbibliothek bleibt erhalten.",
    "home.program.assets": "Datenblätter, Symbolvorschau und vorhandene Footprint-, 3D- und SIM-Informationen ansehen.",
    "home.program.help": "Parametererklärungen, Herkunft, Kennwertart und Messbedingungen stehen im Informationsfeld am Kennwert.",
    "home.program.edit": "Bauteildaten in einem Fenster bearbeiten, Beschreibungsvorschläge bewusst übernehmen und gemeinsam speichern. Ergänzte Kennwerte aus KiCad-Beschreibungen bleiben als ungeprüfte Beschreibungsangaben erkennbar, auch bei Spannungsreferenzen, Reglern und DC-DC-Modulen. Lokale Ergänzungen bleiben beim erneuten Einlesen erhalten.",
    "home.program.models": "Vorhandene SIM-Modelle ansehen und bei Bedarf ändern. Generische KiCad-Modelle bleiben von Herstellermodellen unterscheidbar. Lokale Modelle suchen oder Dateien importieren; Anschlüsse am Symbol zuordnen und speichern. Eindeutige Diodenanschlüsse werden automatisch erkannt; nur unklare Belegungen am Symbol oder Datenblatt bestätigen. Berechenbarkeit mit eigenen Testspannungen und Diodenrichtung bei festen Bedingungen lassen sich separat prüfen; elektrische Genauigkeit und Schaltverhalten bleiben ungeprüft.",
    "home.program.kicad": "Bibliotheksreferenzen kopieren und in KiCad verwenden. Chrome oder Edge empfohlen; bei verweigertem Zwischenablagezugriff die markierte Referenz mit Strg+C kopieren. Windows-Desktopstart über die erstellte Verknüpfung; Linux ist noch nicht vollständig abgenommen.",
    "home.program.use": "So nutzt du es",
    "category.transistors.arrays": "Dual / Arrays",
    "category.transistors.complementary": "Komplementär",
