    "catalog.simPurpose": "Simulationszweck",
    "catalog.clearFilter": "Filter entfernen: {filter}",
    "home.program.step1": "Dual-/Array-Transistoren und eindeutig beschriebene Leistungsmodule haben eigene Kategorien. HW-Entwicklung oder Simulation wählen. Suchbegriffe in beliebiger Reihenfolge eingeben oder Kategorie und Kennwerte eingrenzen. Seltene Filter stehen unter „Weitere Filter“; aktive Zusatzfilter lassen sich direkt entfernen.",
    "home.program.step2": "Kandidaten anhand ihrer Werte und Messbedingungen vergleichen.",
    "home.program.step3": "Datenblatt und Bibliotheksdaten prüfen.",
    "home.program.step4": "Referenz in KiCad verwenden oder ein Modell zuordnen.",
