    "caption.8eacb39167b8": "Alle SIM-Filter müssen zum selben Modell passen. Datei vorhanden bestätigt noch keine Kompatibilität oder elektrische Genauigkeit. Berechenbar bestätigt noch kein Schaltverhalten. Generische Modelle beschreiben keinen bestimmten Herstellerbaustein.",
