    "caption.c42cbece5091": "Lokale Modelle werden gesucht …",
    "caption.17b453a0c77c": " · Name stimmt überein",
    "caption.6e627252a958": "Anderes Modell auswählen",
    "caption.d047e283e430": "SIM-Modell-Anschlüsse links, KiCad-Symbolpins rechts. Bitte die vorgeschlagene Zuordnung prüfen.",
    "caption.2a28ef98f1dc": "SIM-Modell-Anschluss",
    "caption.d25f83dbfee0": "KiCad-Symbolpin",
    "caption.380c4bc706f5": "Einstellungen für Berechenbarkeit",
    "caption.271cd80bbf81": "Nur für „Berechenbarkeit prüfen“: Spannungen der Testschaltung gegen Masse. Der separate Diodenrichtungstest verwendet feste Bedingungen, keine dieser Eingaben. Dein KiCad-Schaltplan bleibt unverändert. Leeres Feld: Anschluss über 1 MΩ an Masse.",
    "caption.612e688edda3": "Bitte zuordnen",
    "caption.5f6721edc216": "Berechenbarkeit prüfen",
    "caption.6ee95355c146": "Zuordnung übernehmen",
    "caption.14f7b3c650c4": "Das Programm prüft das Modell mit einer einfachen Testschaltung. Dein KiCad-Schaltplan wird dabei nicht verändert.",
    "caption.0d6f3a86c6d9": "Für dieses Subcircuit-Modell müssen geeignete Testspannungen in den erweiterten Testeinstellungen festgelegt werden.",
    "caption.d6509255955f": "Details für Experten",
    "caption.175a5d993145": "SIM-Modell wird berechnet …",
    "caption.d2b4c260fbdb": "Prüfergebnis und nächste Schritte",
    "caption.5c114aba813b": "Berechenbarkeit: ",
    "caption.faec0125650b": "Nicht geprüft – zuerst Pinzuordnung korrigieren.",
    "caption.2b4c87aef234": "Berechnung fehlgeschlagen. Testeinstellungen und Modelldatei prüfen; Fehlermeldung unter Details für Experten.",
    "caption.a4fbea110a94": "Pinzuordnung: ",
    "caption.f1544d9329eb": "Nicht geprüft.",
    "caption.c1e3b66f4a19": "Elektrische Genauigkeit und Schaltverhalten: ungeprüft. Für den Einsatz mit Datenblattwerten und einer geeigneten Testschaltung vergleichen.",
    "caption.a6a12c28b593": "Bitte alle Modellanschlüsse einem Symbolpin zuordnen.",
    "caption.4f62bfd63677": "SIM-Zuordnung wird gespeichert …",
    "caption.2e271d7981ab": "Zuordnung oder Testeinstellungen geändert. Bitte erneut prüfen.",
    "caption.f395fe6fca58": "Modelldateien werden eingelesen …",
    "caption.53b1c598e037": "Auswahl zu groß (maximal 10 MB Text).",
    "caption.5e47640615ea": "Eigene Datei",
    "caption.8d6e9288892d": "KiCad-Symbolanschlüsse werden gelesen …",
    "caption.289a41093438": "Symbolpins sind unbenannt. Bitte die Funktion anhand des Symbols oder Datenblatts prüfen und die Pinnummern zuordnen. Es wird keine Anschlussfunktion geraten.",
    "caption.6c0392c74249": "Symbolpins konnten nicht gelesen werden.",
    "caption.500af0d48759": "nicht ermittelt",
    "caption.455803bb379f": "Diodenrichtung prüfen",
    "caption.73bc7bfa367b": "Zuerst die Anschlüsse am gezeigten KiCad-Symbol bestimmen. Diese Angabe ist der Bezug für den Test und wird getrennt von der SIM-Pinzuordnung gewählt. Die Kathode liegt auf der Strichseite des Diodensymbols.",
    "caption.8ef9f60fe41c": "Am Symbol: Anode (A)",
    "caption.39628096e58f": "Am Symbol: Kathode (K, Strichseite)",
    "caption.65e454a59d11": "Bitte am Symbol prüfen",
    "caption.b5d932d7c5b8": " · unbenannt",
    "caption.978b221501dc": "Symbol-Anode und Kathode geprüft",
    "caption.15001c2e4618": "Anode und Kathode am Symbol oder im Datenblatt geprüft.",
    "caption.2dcb9c89afa0": "Diodenrichtung prüfen",
    "caption.1c14aebc0662": "Fester Test: +1 V und −1 V über 1 kΩ bei 25 °C. Vorwärtsstrom mindestens 1 µA, Rückwärtsstrom höchstens 1/10 davon. Keine Datenblatt- oder Schaltzeitprüfung; freie Testspannungen werden hier nicht verwendet.",
    "caption.f3df740d5eb1": "Bei LEDs oder SiC-Dioden reichen 1 V häufig nicht zum Einschalten. Ein fehlgeschlagener Grundtest beweist deshalb allein keine falsche Pinbelegung.",
    "caption.87e63fce5b12": "Pinangaben geändert. Dioden-Grundfunktion erneut prüfen.",
    "caption.415df081a38a": "Durchlass- und Sperrrichtung werden über die Symbolpins geprüft …",
    "caption.ee6239c351e7": "Diodentest fehlgeschlagen.",
    "caption.1941d401b1b6": "Diodenrichtung plausibel",
    "caption.a7727ea48ae6": "Diodenrichtung nicht bestätigt",
    "caption.ef0bb9366454": "Durchlassrichtung (+1 V): ",
    "caption.7fcbc27f985d": "nicht bestanden",
    "caption.1ddc43a84b0b": "bestanden",
    "caption.13c70c59f9aa": "Sperrrichtung (−1 V): ",
    "caption.8942663ad673": "Die Stromrichtung ist unter diesen Testbedingungen plausibel. Der Rückwärtsstrom wurde nicht gegen eine Datenblattgrenze geprüft.",
    "caption.4f4daec7dd80": "Symbolbelegung, SIM-Pinzuordnung und Modell prüfen. Vertauschte Anschlüsse können diese Prüfung scheitern lassen.",
    "caption.bda179fcb744": "Berechnung oder Ergebnisauswertung fehlgeschlagen. Fehlermeldung unter Details für Experten.",
    "caption.d0d429bb706a": "Elektrische Genauigkeit und Schaltverhalten bleiben ungeprüft.",
