    "caption.92134ce6ca97": "Auswertung der aktuellen Ergebnismenge für KiCad-Symbole und Herstellerbauteile. Generische Modelle, Referenzmodelle und reine Footprints sind ausgeschlossen. Standardparameter zählen; optional auswählbare Merkmale sind hier nicht enthalten. Vorhanden bedeutet nicht am Datenblatt geprüft.",
