    "caption.3cd88a32497b": "SIM-Abdeckung · ",
    "caption.36425fde70c4": "Aktuelle gefilterte Ergebnismenge. Gezählt werden Bauteile mit Symbol, keine Modelldefinitionen und keine reinen Footprints. Ein Bauteil kann mehrere Nachweise haben; die Spalten sind deshalb nicht addierbar.",
