    "functionTag.6": "Spannungsregler",
    "program.language": "Oberfläche auf Englisch oder Deutsch verwenden. Ohne gespeicherte Sprachwahl startet das Programm auf Englisch; Kurze Fehlermeldungen erscheinen in der gewählten Sprache; technische Details sind aufklappbar. Originalbeschreibungen und technische Protokolle bleiben in der Quellsprache.",
