    "profiles.advancedDeferred": "Suche geöffnet. Zurückgestellte Filter für Herkunft, Kennwertart und Messbedingungen wurden nicht angewendet.",
    "donate.button": "☕ Kaffee spendieren",
    "donate.title": "Kleiner Kaffee, große Freude.",
    "donate.intro": "Der KiCad Parts Manager läuft mit Elektronen – seine Weiterentwicklung gelegentlich mit Kaffee. ☕",
    "donate.message": "Keiner muss, jeder kann: Wenn dir das Programm hilft, freue ich mich über eine kleine Spende. Wenn viele ein klein wenig meiner Arbeit honorieren, macht mir das Weiterentwickeln riesigen Spaß!",
    "donate.welcome": "Auch ohne Spende bist du hier genauso willkommen. Danke fürs Nutzen, Testen und Mitdenken!",
    "donate.paypal": "Eine Kleinigkeit über PayPal spendieren ↗",
    "donate.later": "Heute nur Elektronen",
    "donate.note": "PayPal öffnet sich in einem neuen Tab. Den Betrag bestimmst du selbst.",
    "donate.statement": "Für Ideen mit Spannung.",
    "home.program.support": "Der Kaffee-Button öffnet eine freiwillige Einladung zur Unterstützung. Erst die Schaltfläche im Fenster führt zu PayPal.",
    "program.libraryImport": "Beim ersten Start ohne Bibliothekskatalog werden installierte KiCad-Bibliotheken erkannt und nach Auswahl lokal eingelesen. Beim Start zeigt ein Ladefenster den laufenden Aufbau des Katalogs an. Unveränderte Bibliotheksdaten werden aus einem lokalen Zwischenspeicher geladen; nach relevanten Änderungen wird dieser automatisch erneuert. Dateien und ZIPs über „Bauteile hinzufügen“ importieren: In drei nebeneinanderliegenden Bereichen Dateien ablegen, Symbolvorschau mit Pinnamen und -nummern sowie Footprint prüfen, vorhandene Kategorie wählen oder eine Unterkategorie anlegen, Bauteilparameter eingeben und speichern. SIM-Hauptmodelle und eindeutige Anschlussfunktionen werden vorgeschlagen; SIM im gemeinsamen Modelldialog suchen, prüfen und für den Import übernehmen oder ohne SIM speichern. TINA-Modelle sind nicht automatisch ngspice-geprüft; elektrische Genauigkeit und 3D-Lage bleiben ungeprüft. Vorhandene Bauteile ergänzen oder nur ausgewählte Angaben / Dateipakete ersetzen; letzten ändernden Import rückgängig machen. Benutzerordner vor dem ersten Import einstellbar. KiCad-Bibliotheken werden mit eigenen Namen ergänzt; offene Zuordnungen und fehlende Einbindung werden angezeigt. Manuelle Kennwerte haben weiterhin Vorrang. Doppelklick im Katalog kopiert den KiCad-Suchnamen; vollständige Referenz über „Referenz kopieren“.",
    "progress.interrupted": "Übertragung unterbrochen. Bitte den Bestand prüfen, bevor du die Aktion wiederholst.",
