    "usage.check": "Before use, check the current manufacturer datasheet, the exact component variant, ratings and test conditions, as well as symbol pins, footprint and 3D dimensions. Selecting a component in this application does not approve it for your circuit.",
    "usage.sim": "An available or calculable SIM model confirms neither electrical accuracy nor switching behavior. A passed model test applies only to its stated test conditions and does not replace verification of the actual circuit.",
    "usage.rights": "External datasheets, libraries and models are subject to their respective owners' licenses and terms. Displaying or linking them in this application grants no additional rights to use or redistribute them.",
    "error.request_failed": "The action could not be completed. Please try again; if it fails again, check the technical details.",
    "error.invalid_request": "The entries could not be processed. Check your inputs and selection. The technical details explain the cause.",
