    "home.title": "KiCad Parts Manager · Your part. Your design.",
    "home.nav.program": "Help & KiCad connection",
    "help.transfer.title": "Place a component in the schematic",
    "help.transfer.pick": "Select a table row. Double-click to copy the search name for KiCad; “Copy reference” in the details panel copies the full library reference.",
    "help.transfer.place": "Press A in the KiCad schematic editor. Paste the reference into the symbol chooser search with Ctrl+V, select the symbol and place it.",
    "help.transfer.check": "Check the footprint and simulation settings in KiCad. Added ratings and newly assigned simulation models are not automatically transferred when copying a standard symbol reference.",
    "help.transfer.missing": "Symbol not found? Add its symbol library under Preferences → Manage Symbol Libraries in KiCad. A footprint is not a schematic symbol; use its reference when assigning footprints.",
    "help.database.title": "Connect KiCad to the local database",
    "help.database.scope": "Optional for the curated database collection. The large library catalog, manual additions and extra model assignments are not yet fully available through this connection.",
    "help.database.driver": "Install a SQLite ODBC driver matching the KiCad architecture. For 64-bit KiCad open the 64-bit ODBC administrator: C:/Windows/System32/odbcad32.exe.",
    "help.database.dsn": "Create a User DSN named kicad-parts-manager in the ODBC administrator. Select the existing SQLite file in the db folder: kicad-parts-manager.sqlite, or componentdb.sqlite in older installations. Use its full path.",
    "help.database.library": "In KiCad choose Preferences → Manage Symbol Libraries → add an existing library. Select kicad/kicad-parts-manager.kicad_dbl in the application folder. Its technical library name is kicad-parts-manager.",
    "help.database.sources": "Also register the source libraries, especially Device, Transistor_FET and Transistor_BJT. Restart the schematic editor after changes to the driver or connection.",
    "help.database.use": "Press A in the schematic, choose the kicad-parts-manager library and search for the component ID displayed in the selection window. Update existing database parts using Tools → Update Symbols from Library.",
    "help.database.limit": "The website itself is not a KiCad database library. JSON export does not place a component. Direct placement by double-clicking in the browser is not yet available.",
