    "help.vr_rms.description": "RMS AC voltage from the description or datasheet. Do not equate it with peak repetitive reverse voltage VRRM.",
    "help.vr_rms.source": "VR(RMS) / RMS reverse voltage",
    "help.vr_rms.use": "Select bridge rectifiers by their stated RMS AC voltage; check waveform and conditions in the datasheet.",
    "help.vr_max.description": "Reverse voltage specification; check the exact voltage rating in the datasheet.",
    "help.vr_max.source": "Reverse Voltage / Absolute Maximum Ratings",
