    "help.insertion_loss.source": "Insertion Loss / test circuit",
    "help.insertion_loss.use": "Compare attenuation only at matching frequency, source/load impedance and measurement mode.",
    "help.loss_frequency.title": "Attenuation reference frequency",
    "help.loss_frequency.description": "Frequency of the specified attenuation value.",
    "help.loss_frequency.source": "Attenuation curve",
    "help.loss_frequency.use": "Use together with insertion loss and test circuit.",
