    "home.hero.context": "TECHNICAL DATA IN CONTEXT",
    "home.hero.title": "From the idea to",
    "home.hero.last": "the right component.",
    "home.hero.description": "Select components. Find datasheets. Prepare simulations.",
    "home.hero.open": "Open component selection",
    "home.more": "Learn more",
    "home.tile.selection": "Component selection",
    "home.tile.selection.short": "Filter by electrical properties",
    "home.tile.selection.detail": "Choose a category, narrow down parameters and compare candidates in the table.",
    "home.tile.selection.action": "Select components",
    "home.tile.simulation": "Simulation",
    "home.tile.simulation.short": "Find and assign SPICE models",
    "home.tile.simulation.detail": "Find or import models, map symbol pins and inspect available test results. Simulation takes place in KiCad.",
    "home.tile.simulation.action": "Prepare simulation",
    "home.tile.libraries": "Libraries",
    "home.tile.libraries.short": "Browse symbols and footprints",
    "home.tile.libraries.detail": "Browse installed libraries, inspect footprints and 3D availability and copy references for KiCad.",
    "home.tile.libraries.action": "Browse footprints",
    "home.stat.symbols": "Symbols",
    "home.stat.facts": "Local manufacturer values",
    "home.stat.modelNote": "These models can be assigned to components.",
    "home.footer.local": "Local inventory · KiCad Parts Manager",
    "home.program.title": "Help & KiCad connection",
    "home.program.intro": "KiCad Parts Manager helps you select components for schematics, PCBs and simulation by their electrical properties. Circuit design and simulation take place in KiCad.",
    "home.program.features": "What you can do",
    "home.program.catalog": "Browse installed libraries with compact category profiles and suitable filters. Additional parameters, temperature and qualifications are selectable. Unclear categories stay neutral; generic SIM models do not claim manufacturer limits. Select resistors by function and capacitors by technology; narrow packages using the package/footprint filter. Search searches the inventory in the current workspace. Selecting a category clears the search; table filters narrow down that group. Apply short queries such as 100nF 0805 or 10mR 2W with Enter: the category and technical filters are set automatically. Resistance, capacitance, inductance and power use suitable units. Their table filters accept units and common notation; without a unit, the unit stated at the input is used. Select switches and relays by function; fuses are under protection components. Jumpers are under connectors, rotary encoders under sensors. Use table filters for contact arrangements and electrical ratings. Save your own category for one or several components, undo the change or restore automatic classification. Choices survive imports; original libraries are retained.",
    "home.program.assets": "View datasheets, symbol previews and available footprint, 3D and SIM information.",
    "home.program.help": "Parameter explanations, origin, value type and measurement conditions appear in the information panel for a value.",
    "home.program.edit": "Edit component data in one window, accept description suggestions deliberately and save together. Added values from KiCad descriptions remain identifiable as unverified description data, including voltage references, regulators and DC-DC modules. Local additions survive rescanning.",
    "home.program.models": "View existing simulation models and change them when needed. Generic KiCad models remain distinguishable from manufacturer models. Search local models or import files; map terminals to symbol pins and save. Unambiguous diode terminals are identified automatically; confirm only unclear pinouts using the symbol or datasheet. Calculability with its own test voltages and diode direction under fixed conditions can be checked separately; electrical accuracy and switching behavior remain unverified.",
    "home.program.kicad": "Copy library references for use in KiCad. Chrome or Edge recommended; if clipboard access is denied, copy the selected reference with Ctrl+C. Windows desktop start uses the created shortcut; Linux has not yet been fully accepted.",
    "home.program.use": "How to use it",
