    "caption.1c14aebc0662": "Fixed test: +1 V and −1 V through 1 kΩ at 25 °C. Forward current at least 1 µA, reverse current at most 1/10 of it. No datasheet accuracy or switching-time check; custom test voltages are not used here.",
