    "donate.button": "☕ Buy me a coffee",
    "donate.title": "A little coffee, a lot of joy.",
    "donate.intro": "KiCad Parts Manager runs on electrons – its development occasionally runs on coffee. ☕",
    "donate.message": "No pressure, just an invitation: if the application helps you, a small donation is always welcome. When many people show a little appreciation for my work, continuing to improve it becomes a whole lot of fun!",
    "donate.welcome": "You are just as welcome without donating. Thanks for using it, testing it and sharing your ideas!",
    "donate.paypal": "Send a little thank-you via PayPal ↗",
    "donate.later": "Just electrons today",
    "donate.note": "PayPal opens in a new tab. You choose the amount.",
    "donate.statement": "Keep the ideas charged.",
    "home.program.support": "The coffee button opens an optional invitation to support development. Only the button in that dialog takes you to PayPal.",
    "program.libraryImport": "On first use without a library catalog, installed KiCad libraries are detected and read locally after selection. A startup screen shows that the catalog is loading. Unchanged library data is loaded from a local cache, which is rebuilt automatically after relevant changes. Import files and ZIPs using “Add components”: use three adjacent sections for files, symbol previews with pin names/numbers, footprints and parameters, select an existing category or create a child category, enter component parameters and save. Main SIM models and unambiguous terminal functions are suggested; search, check and select SIM using the shared model dialog, or save without SIM. TINA models are not automatically verified for ngspice; electrical accuracy and 3D orientation remain unverified. Supplement existing components or replace selected data / file bundles; undo the last import that changed data. Choose the user folder before the first import. KiCad libraries are added under their own names; unresolved assignments and unavailable registration are shown. Manual parameters still take precedence. Double-click in the catalog copies the KiCad search name; use “Copy reference” for the full reference.",
